{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-seat-service' AND span_name='SeatController.getLeftTicketOfInterval' GROUP BY 1,2,3 UNION ALL SELECT 'abnormal', span_name, attr_span_kind, count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='SeatController.getLeftTicketOfInterval' GROUP BY 1,2,3",
          "claim": "Seat's SeatController.getLeftTicketOfInterval self-time rises from about 8 ms to about 78 ms average."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, c.service_name AS callee, round(avg(p.duration)/1e6,1) AS caller_client_ms, round(avg(c.duration)/1e6,1) AS callee_server_ms, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name IN ('ts-travel-plan-service','ts-travel2-service') AND p.span_name='POST' AND c.span_name='POST /api/v1/seatservice/seats/left_tickets' GROUP BY ALL",
          "claim": "Travel-plan and travel2 client calls to seat left_tickets take about 72-121 ms, matching the callee server time, so there is no transport gap."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, round(avg(duration)/1e6,1) ms, count(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='GET' AND attr_span_kind='Client' GROUP BY 1,2",
          "claim": "Seat's own outgoing GET calls to config-service have short child spans (~3 ms), so extra time is spent inside seat's method rather than downstream."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, round(avg(duration)/1e6,1) ms, count(*) n FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2,3",
          "claim": "Travel-plan server spans for cheapest/quickest/minStation average 150-495 ms, with the time spent waiting on seat calls."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(avg(duration)/1e6,1) ms, count(*) n FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2",
          "claim": "Travel2 trips/left server spans average about 25 ms, up from about 23 ms, while calling seat left_tickets that takes about 72 ms."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH a AS (SELECT 'normal' p, span_name, count(*) c, round(avg(duration)/1e6,1) ms FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 2), b AS (SELECT 'abnormal' p, span_name, count(*) c, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 2) SELECT * FROM a UNION ALL SELECT * FROM b",
          "claim": "Dashboard's user-facing travelPlan cheapest and quickest requests rise from about 55 ms to about 260-360 ms average."
        }
      ]
    }
  ]
}
